import javax.microedition.lcdui.*;
import java.awt.image.BufferedImage;
import java.io.File;
import java.lang.reflect.Method;
public final class CanvasChecks implements NWalletCanvas.Host {
 private static int checks;private int saved,connections,locks,exits,consents;private boolean fail;private String submitted;
 public void createSampleRoot(int words){}public void approveWallet(boolean allow){}public void cancelWallet(){}
 public void connect(){connections++;}public void lock(){locks++;}public void exit(){exits++;}public void settings(int item){}
 public void saveLanguage(int value)throws Exception{if(fail)throw new Exception("disk");saved=value;}public void submitPin(String pin){submitted=pin;}public void allowConnection(boolean allow){consents++;}
 private static void check(boolean value,String message){if(!value)throw new RuntimeException(message);checks++;}
 private static void key(NWalletCanvas c,int key)throws Exception{event(c,"keyPressed",key);event(c,"keyReleased",key);}
 private static void event(NWalletCanvas c,String name,int key)throws Exception{Method m=NWalletCanvas.class.getDeclaredMethod(name,Integer.TYPE);m.setAccessible(true);m.invoke(c,Integer.valueOf(key));}
 private static void render(NWalletCanvas c,String name)throws Exception{c.status(c.navigation().language()==0?"未连接":"Offline",c.navigation().language()==0?"样本已解锁":"Sample unlocked",c.navigation().language()==0?"尚未连接":"No peer",c.navigation().language()==0?"无":"None",false);BufferedImage image=new BufferedImage(240,320,BufferedImage.TYPE_INT_RGB);Method paint=NWalletCanvas.class.getDeclaredMethod("paint",Graphics.class);paint.setAccessible(true);paint.invoke(c,new Graphics(image));javax.imageio.ImageIO.write(image,"png",new File(System.getProperty("nwallet.test.output","build/evidence"),name+".png"));}
 public static void main(String[] args)throws Exception{CanvasChecks host=new CanvasChecks();NWalletCanvas c=new NWalletCanvas(host,0);c.status("未连接","样本已解锁","尚未连接","无",false);render(c,"native-home-zh");
  key(c,-4);render(c,"native-settings-zh");key(c,-2);key(c,-2);key(c,-5);key(c,-2);check(c.navigation().language()==0,"browsing changed language");render(c,"native-language-draft");host.fail=true;key(c,-7);check(c.navigation().language()==0,"failed persistence applied language");host.fail=false;key(c,-7);check(c.navigation().language()==1&&host.saved==1,"right select/save");key(c,-1);key(c,-5);check(c.navigation().language()==0,"center select/save");key(c,-2);key(c,-5);key(c,-6);render(c,"native-settings-en");key(c,-4);render(c,"native-about-en");
  c.chooseRoot();render(c,"native-root");key(c,-6);c.confirmWallet("公开样本根：12词\npassphrase：·a·\n首尾空格保留。只打开钱包，不批准交易。");render(c,"native-passphrase");c.walletProgress("公开样本实际派生中…\n左软键取消");render(c,"native-progress");c.walletResult("钱包已打开","公开地址已完整派生\n右软键返回");render(c,"native-result");c.invalidateConsent();String address="0x52908400098527886E0F7030069857D2E4169EE7";String[] lines=NWalletCanvas.wrap(address,111,Font.getFont(0,0,8));String joined="";for(String line:lines)joined+=line;check(address.equals(joined),"wrap changed EIP55");check(lines.length>1,"wrap not exercised");String unicode="Aa  \ud83d\ude00z ";lines=NWalletCanvas.wrap(unicode,20,Font.getFont(0,0,8));joined="";for(String line:lines){joined+=line;check(line.length()==0||!Character.isLowSurrogate(line.charAt(0)),"split surrogate");}check(unicode.equals(joined),"wrap changed spaces/case");
  key(c,-3);key(c,-5);key(c,-1);key(c,-5);key(c,-6);c.pin("设置样本 PIN","输入4–12位数字；中键继续。");key(c,-5);check(host.submitted==null,"empty PIN submitted");key(c,48);key(c,48);key(c,49);key(c,50);render(c,"native-pin");key(c,-5);check("0012".equals(host.submitted),"leading zero lost");check(host.connections==0,"PIN leaked actions");c.unlocked();c.consent("未知平台");event(c,"keyRepeated",-7);check(host.consents==0,"repeat approved consent");key(c,-5);check(host.consents==0,"center approved consent");key(c,-7);check(host.consents==1,"right did not allow");
  NWalletPreferences p=new NWalletPreferences();check(!p.configured(),"fresh configured");p.setPin("0012");check(p.verify("0012")&&!p.verify("12")&&!p.verify("0013"),"PIN comparison");p.language(1);p=new NWalletPreferences();check(p.language()==1&&p.verify("0012"),"preference roundtrip");javax.microedition.rms.RecordStore.fail=true;try{p.language(0);throw new RuntimeException("expected storage failure");}catch(Exception expected){check(p.language()==1,"failed save changed preference");}
  System.out.println("PASS "+checks+" desktop Canvas/PIN/preferences checks; AWT metrics and fake RMS, not C5 acceptance");
 }
}
